// Pecah pesan panjang menjadi beberapa bagian <= 1900 karakter (buffer dari limit 2000 Discord)
// supaya tidak pernah kena "Invalid Form Body" karena terlalu panjang.

const MAX_LEN = 1900;
const items = $input.all();
const output = [];

for (const item of items) {
  let text = item.json.output || '';

  // Fallback kalau output kosong total
  if (!text || text.trim() === '') {
    text = 'Maaf Kak, HUMI lagi agak bingung jawabnya nih 😅 Boleh diulang pertanyaannya?';
  }

  if (text.length <= MAX_LEN) {
    output.push({ json: { ...item.json, output: text, part: 1, totalParts: 1 } });
    continue;
  }

  // Pecah berdasarkan paragraf/baris dulu (supaya tidak memotong di tengah kalimat/produk)
  const lines = text.split('\n');
  const chunks = [];
  let current = '';

  for (const line of lines) {
    if ((current + '\n' + line).length > MAX_LEN) {
      if (current) chunks.push(current.trim());
      current = line;
    } else {
      current = current ? current + '\n' + line : line;
    }
  }
  if (current) chunks.push(current.trim());

  // Kalau ada satu baris tunggal yang masih > MAX_LEN (jarang terjadi), potong paksa per karakter
  const finalChunks = [];
  for (const c of chunks) {
    if (c.length <= MAX_LEN) {
      finalChunks.push(c);
    } else {
      for (let i = 0; i < c.length; i += MAX_LEN) {
        finalChunks.push(c.slice(i, i + MAX_LEN));
      }
    }
  }

  finalChunks.forEach((chunk, idx) => {
    output.push({
      json: {
        ...item.json,
        output: chunk,
        part: idx + 1,
        totalParts: finalChunks.length
      }
    });
  });
}

return output;
